BEGIN;

DELETE FROM point_transactions WHERE user_id IN (SELECT id FROM users WHERE name IN ('Alex', 'Георгий'));
DELETE FROM domain_events WHERE user_id IN (SELECT id FROM users WHERE name IN ('Alex', 'Георгий'));
DELETE FROM streaks WHERE user_id IN (SELECT id FROM users WHERE name IN ('Alex', 'Георгий'));
DELETE FROM habit_milestone_clears WHERE user_id IN (SELECT id FROM users WHERE name IN ('Alex', 'Георгий'));
DELETE FROM achievements WHERE user_id IN (SELECT id FROM users WHERE name IN ('Alex', 'Георгий'));
DELETE FROM daily_stats WHERE user_id IN (SELECT id FROM users WHERE name IN ('Alex', 'Георгий'));
DELETE FROM day_settlements WHERE user_id IN (SELECT id FROM users WHERE name IN ('Alex', 'Георгий'));
DELETE FROM tasks WHERE goal_id IN (SELECT id FROM goals WHERE user_id IN (SELECT id FROM users WHERE name IN ('Alex', 'Георгий')));
DELETE FROM milestones WHERE goal_id IN (SELECT id FROM goals WHERE user_id IN (SELECT id FROM users WHERE name IN ('Alex', 'Георгий')));
DELETE FROM habit_streak_milestones WHERE habit_id IN (SELECT id FROM habits WHERE user_id IN (SELECT id FROM users WHERE name IN ('Alex', 'Георгий')));
DELETE FROM goals WHERE user_id IN (SELECT id FROM users WHERE name IN ('Alex', 'Георгий'));
DELETE FROM habits WHERE user_id IN (SELECT id FROM users WHERE name IN ('Alex', 'Георгий'));
DELETE FROM users WHERE name IN ('Alex', 'Георгий');

VALUES ('a0000000-0000-4000-8000-000000000001', 'alex@orbit.dev', '', 'Alex', '2026-06-25T06:00:00Z');









WITH RECURSIVE days(d) AS (
  SELECT date '2026-06-25'
  UNION ALL
  SELECT d + 1 FROM days WHERE d < date '2026-08-08'
),
habits_base(habit_id, base, ord, start, t_off) AS (VALUES
  ('b0000000-0000-4000-8000-000000000001'::uuid, 10, 1, date '2026-07-21', 3.5),
  ('b0000000-0000-4000-8000-000000000002'::uuid, 8, 2, date '2026-07-27', 9.0),
  ('b0000000-0000-4000-8000-000000000003'::uuid, 8, 3, date '2026-07-17', 19.0),
  ('b0000000-0000-4000-8000-000000000004'::uuid, 12, 4, date '2026-07-08', 12.0),
  ('b0000000-0000-4000-8000-000000000005'::uuid, 8, 5, date '2026-07-30', 10.5),
  ('b0000000-0000-4000-8000-000000000006'::uuid, 4, 6, date '2026-06-29', 5.0)
),
active AS (
  SELECT h.habit_id, h.base, h.ord, h.t_off, d.d, d.d - h.start + 1 AS streak_days
  FROM habits_base h JOIN days d ON d.d BETWEEN h.start AND date '2026-08-07'
),
bonused AS (
  SELECT a.*, COALESCE(sm.bonus_xp, 0) AS bonus
  FROM active a
  LEFT JOIN habit_streak_milestones sm ON sm.habit_id = a.habit_id AND sm.days = a.streak_days
),
capped AS (
  SELECT b.*,
         GREATEST(0, LEAST(b.base + b.bonus,
           50 - COALESCE(SUM(b.base + b.bonus) OVER (PARTITION BY b.d ORDER BY b.ord ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING), 0))) AS awarded
  FROM bonused b
),
split AS (
  SELECT c.*,
         LEAST(c.awarded, c.base) AS base_awarded,
         GREATEST(0, c.awarded - LEAST(c.awarded, c.base)) AS bonus_awarded
  FROM capped c
),
ev AS (
  SELECT md5(c.habit_id::text || c.d::text)::uuid,
         'a0000000-0000-4000-8000-000000000001',
         'habit_completed', 'habit', c.habit_id,
         jsonb_build_object('base_xp', c.base, 'bonus_xp', c.bonus, 'awarded', c.awarded, 'streak_days', c.streak_days),
         (c.d + (c.t_off::text || ' hours')::interval)::timestamptz
  FROM split c
),
tx1 AS (
  SELECT 'a0000000-0000-4000-8000-000000000001', 'xp', s.base_awarded, 'habit_completed',
         md5(s.habit_id::text || s.d::text)::uuid,
         (s.d + (s.t_off::text || ' hours')::interval)::timestamptz
  FROM split s
  WHERE s.base_awarded > 0
),
tx2 AS (
  SELECT 'a0000000-0000-4000-8000-000000000001', 'xp', s.bonus_awarded, 'streak_milestone',
         md5(s.habit_id::text || s.d::text)::uuid,
         (s.d + (s.t_off::text || ' hours')::interval)::timestamptz
  FROM split s
  WHERE s.bonus_awarded > 0
)
SELECT 1;





WITH RECURSIVE days(d) AS (
  SELECT date '2026-06-25'
  UNION ALL
  SELECT d + 1 FROM days WHERE d < date '2026-08-08'
),
habits_base(habit_id, base, ord, start, t_off) AS (VALUES
  ('b0000000-0000-4000-8000-000000000001'::uuid, 10, 1, date '2026-07-21', 3.5),
  ('b0000000-0000-4000-8000-000000000002'::uuid, 8, 2, date '2026-07-27', 9.0),
  ('b0000000-0000-4000-8000-000000000003'::uuid, 8, 3, date '2026-07-17', 19.0),
  ('b0000000-0000-4000-8000-000000000004'::uuid, 12, 4, date '2026-07-08', 12.0),
  ('b0000000-0000-4000-8000-000000000005'::uuid, 8, 5, date '2026-07-30', 10.5),
  ('b0000000-0000-4000-8000-000000000006'::uuid, 4, 6, date '2026-06-29', 5.0)
),
active AS (
  SELECT h.habit_id, h.base, h.ord, h.t_off, d.d, d.d - h.start + 1 AS streak_days
  FROM habits_base h JOIN days d ON d.d BETWEEN h.start AND date '2026-08-07'
),
bonused AS (
  SELECT a.*, COALESCE(sm.bonus_xp, 0) AS bonus
  FROM active a
  LEFT JOIN habit_streak_milestones sm ON sm.habit_id = a.habit_id AND sm.days = a.streak_days
),
capped AS (
  SELECT b.*,
         GREATEST(0, LEAST(b.base + b.bonus,
           50 - COALESCE(SUM(b.base + b.bonus) OVER (PARTITION BY b.d ORDER BY b.ord ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING), 0))) AS awarded
  FROM bonused b
),
split AS (
  SELECT c.*,
         LEAST(c.awarded, c.base) AS base_awarded,
         GREATEST(0, c.awarded - LEAST(c.awarded, c.base)) AS bonus_awarded
  FROM capped c
)
SELECT 'a0000000-0000-4000-8000-000000000001', d.d,
       COALESCE(h.habit_xp, 0) + COALESCE(t.task_xp, 0) + COALESCE(p.penalty_xp, 0),
       COALESCE(h.habit_xp, 0), COALESCE(t.task_xp, 0), COALESCE(p.penalty_xp, 0),
       COALESCE(t.gpp, 0), COALESCE(t.tasks, 0), COALESCE(h.habits, 0)
FROM days d
LEFT JOIN (SELECT d, sum(awarded) AS habit_xp, count(*) AS habits FROM split GROUP BY d) h ON h.d = d.d
LEFT JOIN (VALUES
  (date '2026-06-30', 5, 10, 1),
  (date '2026-07-01', 20, 20, 1),
  (date '2026-07-06', 60, 40, 1),
  (date '2026-07-08', 67, 55, 2),
  (date '2026-07-12', 20, 20, 1),
  (date '2026-07-15', 105, 80, 2),
  (date '2026-07-16', 5, 10, 1),
  (date '2026-07-20', 300, 150, 2),
  (date '2026-07-22', 120, 80, 2),
  (date '2026-07-26', 75, 50, 1),
  (date '2026-08-02', 35, 35, 1),
  (date '2026-08-03', 150, 100, 2),
  (date '2026-08-07', 20, 20, 1)
) AS t(d, task_xp, gpp, tasks) ON t.d = d.d
LEFT JOIN (VALUES (date '2026-08-05', -10)) AS p(d, penalty_xp) ON p.d = d.d
WHERE d.d < date '2026-08-08';

VALUES ('a0000000-0000-4000-8000-000000000001', '2026-08-08', 22, 22, 0, 0, 0, 0, 3);

SELECT 'a0000000-0000-4000-8000-000000000001', generate_series(date '2026-06-24', date '2026-08-07', interval '1 day')::date;

COMMIT;
